/**
 * Links that open a new tab. Selenium drives one tab at a time: after the click, the driver switches
 * to the new tab, and the next page object uses it from there. The tab the test started in stays
 * open behind it (driver.switchTo().window(...) goes back).
 */
public final class Tabs {
    private Tabs() {
    }

    /** Runs the click, waits for the tab it opens, switches the driver to it and returns the driver. */
    public static WebDriver opened(WebDriver driver, Runnable click) {
        return opened(driver, "the link", click);
    }

    /**
     * As above, naming what was clicked: when no tab opens, the failure says where this tab went instead
     * (an AssertionError, so the message reaches the step log without Selenium's build and driver lines).
     */
    public static WebDriver opened(WebDriver driver, String label, Runnable click) {
        String from = driver.getCurrentUrl();
        Set<String> before = new HashSet<>(driver.getWindowHandles());
        click.run();
        String[] opened = new String[1];
        boolean found = WaitActions.until(() -> {
            for (String handle : driver.getWindowHandles()) {
                if (!before.contains(handle)) {
                    opened[0] = handle;
                    return true;
                }
            }
            return false;
        }, WaitActions.elementTimeout());
        if (!found) {
            String now = driver.getCurrentUrl();
            throw new AssertionError("Clicking " + label + " opened no new tab within " + WaitActions.seconds(WaitActions.elementTimeout()) + " s; "
                    + (now.equals(from) ? "this tab stayed on " + now : "this tab went to " + now + " instead"));
        }
        return driver.switchTo().window(opened[0]);
    }

    // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
    // ==== END YOURS (extras) ====
}
